select fp.finprod_market_id as finprodId, fp.finprod_id as bondId, fp.finprod_abbr as bondName, fp.vdate as vdate, fp.mdate as mdate, fp.coupon_species as couponType, fpt.type_4 as bondType1, fpt.type_5 as bondType2, (fri.rate)*100 as rate, fri.basis as basis, fp.issue_price as price from FIN_PRODUCT fp left join FIN_PRODUCT_TYPE fpt on fp.finprod_id = fpt.finprod_id left join FIN_CASH_INFO fci on fci.finprod_id = fp.finprod_id and fci.finprod_type = #{finprodType} and fci.cash_type_2 = #{cashType} left join FIN_RATE_INFO fri on fri.cash_id = fci.cash_id and fri.eff_date = fp.vdate where fp.FINPROD_TYPE = #{finprodType}
AND vfp.finprod_id in
#{bond}
AND vfp.coupon_species in
#{couponType}
AND fpt.type_1 in
#{bondType1}
AND fpt.type_2 in
#{bondType2}
AND vfp.vdate >= STR_TO_DATE(#{vDateBegin},'%Y-%m-%d')
AND vfp.vdate <=STR_TO_DATE(#{vDateEnd},'%Y-%m-%d')
AND vfp.mdate >=STR_TO_DATE(#{mDateBegin},'%Y-%m-%d')
AND vfp.mdate <= STR_TO_DATE(#{mDateEnd},'%Y-%m-%d')

SELECT FINPROD_ID id, concat_ws('',FINPROD_ABBR,':',FINPROD_MARKET_ID) text FROM FIN_PRODUCT
FINPROD_TYPE2 = #{assestType}
AND ( FIN_PRODUCT.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) OR FIN_PRODUCT.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND FINPROD_ID = #{initValue}
AND FINPROD_ID NOT IN( SELECT O_FINPROD_ID FROM FIN_PRODUCT WHERE O_FINPROD_ID IS NOT NULL )
